update champion_skills set skill_name='Pyrenei Power', skill_summary='Attacks all enemies. Before attacking, places a 50% [Increase ACC] buff on all allies for 2 turns. Has a 75% chance of placing a [HP Burn] debuff on all enemies for 2 turns. Fills this Champion''s Turn Meter by 20% for each [HP Burn] debuff placed on enemies, and fills this Champion''s Turn Meter by 10% for each [HP Burn] debuff resisted by enemies.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Infernal Eruption" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='4ff3953d-6213-4f49-b9e7-b746ec939010' and slot='A3';
update champion_skills set skill_name='Underflame''s Protection', skill_summary='[Active Effect] Activates a [Delay] effect on this Champion whenever they receive a fatal hit. [Passive Effect] Heals this Champion by 20% of their MAX HP whenever a [HP Burn] debuff is activated on an enemy. Whenever a [HP Burn] debuff on an enemy expires or is removed, places a [True Fear] debuff on that enemy for 1 turn.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Underflame''s Resilience" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='4ff3953d-6213-4f49-b9e7-b746ec939010' and slot='A4';

