update champion_skills set skill_name='Seismic Dissonance', skill_summary='Attacks all enemies 2 times. After the first hit, has a 75% chance of placing a 60% [Decrease DEF] debuff and a 25% [Weaken] debuff on all enemies for 2 turns. These debuffs cannot be resisted by Bosses. After the second hit, has a 75% chance of placing a 50% [Decrease ACC] debuff and a 50% [Decrease RES] debuff on all enemies for 2 turns. These debuffs cannot be resisted by Bosses.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Overwhelming Curse" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='6d6ca3ef-877b-4fec-b855-b1a3e981be51' and slot='A2';
update champion_skills set skill_name='Mindless Muscle', skill_summary='Places a [Counterattack] buff on all allies for 2 turns, and an [Unkillable] buff on allies for 1 turn. Also places a [Taunt] buff on this Champion for 2 turns. If a Boss is present in the current Round, these buffs are protected.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Keyhulk''s Guard" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='6d6ca3ef-877b-4fec-b855-b1a3e981be51' and slot='A3';
update champion_skills set skill_name='Drone of Agony', skill_summary='Whenever this Champion places a debuff on an enemy, deals damage equal to 1% of their MAX HP for each debuff they are currently under. (Stacks up to 10%). Occurs once per skill and once per target.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Debilitating Force" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='6d6ca3ef-877b-4fec-b855-b1a3e981be51' and slot='Passive';

