update champion_skills set skill_name='Unwelcome Guest', skill_summary='Attacks 1 enemy. Places a [Petrification] debuff for 1 turn. Has a 75% chance of placing a [True Fear] debuff for 2 turns on all other enemies who are not under a [Fear] or [True Fear] debuff. [Passive Effect] Activates this skill whenever an enemy under a [Fear] or [True Fear] debuff successfully uses a skill. If there are multiple Champions on the team with this skill, only one will activate.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Chilling Performance" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='adb6e11c-4e72-49ab-b096-91904ae9ecb9' and slot='A2';
update champion_skills set skill_name='Spectral Flourish', skill_summary='Attacks all enemies. Before attacking, has a 75% chance of decreasing the duration of all enemy buffs by 3 turns. Has a 75% chance of increasing the cooldowns of all enemy skills by 3 turns. Grants an Extra Turn if there are no buffs on the enemy team after this attack.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Grand Finale" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='adb6e11c-4e72-49ab-b096-91904ae9ecb9' and slot='A3';
update champion_skills set skill_name='Ghost With The Most', skill_summary='Whenever an enemy is revived, places a [True Fear] debuff on that enemy for 2 turns. If there are multiple Champions on the team with this skill, this effect will only activate once. Removes any [Stun], [Freeze], [Provoke], [Fear], [True Fear], and [Petrification] debuffs from this Champion before the start of their turn.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Unending Encore" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='adb6e11c-4e72-49ab-b096-91904ae9ecb9' and slot='Passive';

