update champion_skills set skill_name='Atrophic Ax', skill_summary='Attacks 1 enemy. Has an 80% chance of placing a 25% [Weaken] debuff for 2 turns. This debuff cannot be resisted if the target has attacked this Champion before this turn.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Astropic Axe" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='597f0699-f70e-4842-9398-959fcbef5a38' and slot='A1';
update champion_skills set skill_name='Spirit Calculus', skill_summary='The HP levels of all allies will be brought up to the level of the ally with the highest HP. The Turn Meter levels of all allies will be brought up to the level of the ally with the highest Turn Meter. The HP levels of all enemies will be brought down to the level of the enemy with the lowest HP. The Turn Meter levels of all enemies will be brought down to the level of the enemy with the lowest Turn Meter. Then places a [Taunt] buff on this Champion for 2 turns.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Unity''s Equilibrium" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='597f0699-f70e-4842-9398-959fcbef5a38' and slot='A2';
update champion_skills set skill_name='Finality Disc', skill_summary='Attacks 1 enemy. Before attacking, transfers all debuffs from this Champion to the target and heals this Champion by 10% of their MAX HP. Heals by an additional 10% of their MAX HP for each debuff transferred. Will always use this skill instead of the default skill when counterattacking.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Spirit Siphon" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='597f0699-f70e-4842-9398-959fcbef5a38' and slot='A3';
update champion_skills set skill_name='The Representation', skill_summary='Every time this Champion loses 25% HP or more from a single hit, places a [Block Damage] buff on this Champion for 1 turn. ★★★ Knights Revenant Unity ★★★ 1 Faction Ally: When attacked, has a 15% chance of placing a [True Fear] debuff on the attacker for 1 turn. This debuff cannot be resisted. 2 Faction Ally: Ignore DEF effects against this Champion are decreased by 100%. 3 Faction Ally: When attacked, has a 20% chance of activating an [Instant Turn] effect on this Champion. Occurs once per skill.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Grand Protector" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='597f0699-f70e-4842-9398-959fcbef5a38' and slot='Passive';

