update champion_skills set skill_name='Nurtured Friendship', skill_summary='Removes all debuffs from all allies, then fills the Turn Meters of all allies by 15%. Fills the Turn Meters of each ally by an extra 5% for each debuff removed from them. Increases the RES of allies by 5 for each debuff removed. Grants an Extra Turn if 5 or more debuffs were removed.', source='AyumiLove (human-read factual skill text) 2026-08-07 — name-corruption fix, bad-bulk audit', verification_status='proposed', review_notes='Name-only corruption fix: prior name "Resolute Cleanse" (worksheet Skills tab 2026-07-11 bulk, invented). Name+summary refreshed from AyumiLove; mechanics matched in the audit.' where champion_id='f36fc02d-fa99-4111-a751-ddc711de9741' and slot='A3';
